  'lkvs.name': 'LKV Saxony Feed Laboratory',
  'lkvs.description':
    'This plugin establishes the connection to the feed laboratory of the LKV Sachsen.',
  'lkvs.input_description':
    'With the following three steps you activate your laboratory interface:<ol><li>Please activate this plugin by clicking on the "Activate" button below to get your feed analyses directly transferred from this laboratory to fodjan.</li><li>Please enter your customer number of your laboratory in the field "Customer number". You will find these on your previous feed analyses or invoices, for example.</li><li>If you use the sample submission form from fodjan, we will automatically receive a copy of all your feed analyses directly from the laboratory to make them available to you in fodjan under "Análisis de alimentación".</li></ol><br><strong>Encontrará el formulario de envío de muestras en la vista "Análisis de feeds", arriba a la derecha.</strong>',
  'lkvs.setup_description':
    'Para que tus análisis LKV Sachsen también se importen en fodjan, sigue estos 3 pasos.',
  'BLGG.name': 'eurofins Agro DE',
  'BLGG.description':
    'This plugin establishes the connection to the feed laboratory of Eurofins Analytics.',
  'BLGG.input_description':
    'With the following three steps you activate your laboratory interface:<ol><li>Please activate this plugin by clicking on the "Activate" button below to get your feed analyses directly transferred from this laboratory to fodjan.</li><li>Please enter your customer number of your laboratory in the field "Customer number". You will find these on your previous feed analyses or invoices, for example.</li><li>If you use the sample submission form from fodjan, we will automatically receive a copy of all your feed analyses directly from the laboratory to make them available to you in fodjan under "Feed analyses".</li></ol><br><strong>You will find the sample submission form in the "Feed analyses" view at the top right.</strong>',
  'BLGG.setup_description':
    'Um Ihre eurofins-Analysen auch in fodjan importiert zu bekommen, folgen Sie diesen 2 Schritten.',
  'BAYWA.name': 'BayWa (BLGG)',
  'BAYWA.description':
    'This plugin establishes the connection to the feed laboratory of Eurofins Analytics (personalized for BayWa).',
  'BAYWA.input_description':
    'Mit den folgenden drei Schritten aktivieren Sie Ihre Laborschnittstelle:<ol><li>Bitte aktivieren Sie mit dem Klick auf den „Aktivieren“-Button  unten dieses Plugin, um Ihre Futteranalysen von diesem Labor direkt zu fodjan übertragen zu bekommen.</li><li>Bitte tragen Sie in das Feld „Kundennummer“ Ihre Debitoren-/Kundennummer Ihres Labors ein. Diese finden Sie zum Beispiel auf Ihren früheren Analysen oder Rechnungen.</li><li>Nutzen Sie den Probenbegleitschein aus fodjan, dann bekommen wir automatisch eine Kopie aller Ihrer Analysen direkt vom Labor, um Sie Ihnen in fodjan unter „Futteranalysen“ zur Verfügung zu stellen.</li></ol><br><strong>Den Probenbegleitschein finden Sie oben rechts in der Ansicht „Futteranalysen“</strong>.',
  'BAYWA.setup_description':
    'Um Ihre eurofins-Analysen auch in fodjan importiert zu bekommen, folgen Sie diesen 2 Schritten.',
  'food.name': 'SGS Analytics (formerly Synlab)',
  'food.description':
    'This plugin establishes the connection to the feed laboratory of SGS Analytics.',
  'food.input_description':
    'With the following three steps you activate your laboratory interface:<ol><li>Please activate this plugin by clicking on the "Activate" button below to get your feed analyses directly transferred from this laboratory to fodjan.</li><li>Please enter your customer number of your laboratory in the field "Customer number". You will find these on your previous feed analyses or invoices, for example.</li><li>If you use the sample submission form from fodjan, we will automatically receive a copy of all your feed analyses directly from the laboratory to make them available to you in fodjan under "Feed analyses".</li></ol><br><strong>You will find the sample submission form in the "Feed analyses"</strong> view at the top right.',
  'food.setup_description':
    'To get your SGS Analytics feed analyses imported into fodjan, follow these 3 steps.',
  'lkvbb.name': 'LKV BB Feed Laboratory',
  'lkvbb.description':
    'This plugin establishes the connection to the feed laboratory of the LKV Berlin-Brandenburg.',
  'lkvbb.input_description':
    'With the following three steps you activate your laboratory interface:<ol><li>Please activate this plugin by clicking on the "Activate" button below to get your feed analyses directly from this laboratory to fodjan.</li><li>If you use the sample submission form from fodjan, then we automatically get a copy of all your feed analyses directly from the laboratory to make them available to you in fodjan under "Feed analyses". For the feed laboratory of the LKV Berlin/Brandenburg you do not need your own customer number. After you have sent the first test order via fodjan, the assignment takes place via fodjan´s own customer number.</li></ol><br><strong>You will find the sample submission form at the top right in the view "Feed analyses"</strong>.',
  'lkvbb.setup_description':
    'To get your LKV BB feed analyses imported into fodjan, follow these 2 steps.',
  'lufanw.name': 'LUFA Nordwest',
  'lufanw.description':
    'This plugin establishes the connection to the feed laboratory of the LUFA Nord-West.',
  'lufanw.input_description':
    'With the following three steps you activate your laboratory interface:<ol><li>Please activate this plugin by clicking on the "Activate" button below to get your feed analyses directly transferred from this laboratory to fodjan.</li><li>Please enter your customer number of your laboratory in the field "Customer number". You will find these on your previous feed analyses or invoices, for example.</li><li>If you use the sample submission form from fodjan, we will automatically receive a copy of all your feed analyses directly from the laboratory to make them available to you in fodjan under "Feed analyses".</li></ol><br><strong>You will find the sample submission form in the "Feed analyses"</strong> view at the top right.',
  'lufanw.setup_description':
    'To get your Lufa NW feed analyses imported into fodjan, follow these 3 steps.',
