  'lab_euf_nl.description':
    'This plugin establishes the connection to the feed laboratory of Eurofins NL Analytics.',
  'lab_euf_nl.input_description':
    'Con los tres pasos siguientes activará la interfaz de su laboratorio:<ol><li>Active este plugin haciendo clic en el icono "Activate" para que sus análisis se transfieran directamente de este laboratorio a fodjan.</li><li>Introduzca el número de cliente de su laboratorio en el campo "Número de cliente". Lo encontrará en sus análisis o facturas anteriores, por ejemplo.</li><li>Si utiliza el formulario de envío de muestras de fodjan, recibiremos automáticamente una copia de todos sus análisis directamente del laboratorio para ponerlos a su disposición en fodjan bajo "Feed analyses".</li></ol><br><strong>You will find the sample submission form in the "Feed analyses" view at the top right.</strong>',
