  'kee_fmw.name': 'Keenan Feed Mixer & Milk Data',
  'kee_fmw.kee_fmw': 'Exports your planned rations to your Keenan feed mixer.',
  'kee_fmw.description':
    'This plugin connects to a Keenan feed mixer and transfers the planned rations to the mixer and the loaded quantities back to fodjan.',
