  'Ration bearbeiten': 'Edit Ration',
  'felleskjopet.description': ' ',
  'fodjan smart feeding ist eine neue Generation landwirtschaftlicher Fütterungssoftware für Landwirte, Fütterungsberater und Tierärzte. Das innovative Programm vereinfacht die Rationsberechnung und vernetzt Sie im gesamten Fütterungsprozess: Vom Futtermittelmanagement über den Futtermischwagen und ihren Mitarbeitern bis hin zu Laboren, uvm. Betriebseffizienz und Tiergesundheit stehen dabei im Fokus. fodjan ist als App und für den Desktop erhältlich und füttert Milchkühe, Mastrinder und Schweine.':
    'fodjan smart feeding is a new generation of agricultural feeding software for farmers, feed advisers and veterinarians. The innovative programm simplifies feed ration calculation/formulation and keeps you connected within the whole feeding process: From your feed mixer, to employees, to laboratories, etc. Thereby efficiency and animal health are central. Fodjan is available as app and for your desktop and feeds dairy cows, beef cattle and fattening pigs.',
  'Das Rationsberechnungsprogramm fodjan smart feeding wurde speziell für Milchviehhalter entwickelt und bewertet die Futtergesundheit Ihrer Ration, um Folgen falscher Fütterung, die zu Milchfieber, Pansenazidose und Klauenerkrankungen führen können, vorzubeugen. Gleichzeitig haben Sie Überblick über aktuelle wirtschaftliche Kennzahlen Ihres Betriebs und die Möglichkeit zur Optimierung Ihrer Ration hinsichtlich Futterkosten, -effizienz, Milchmenge, IOFC uvm .  Wir geben Ihnen die Möglichkeit auf aktuelle Regulatorien – wie z.B. Düngeverordnung und GVO-freie Fütterung - zu reagieren. Probieren Sie fodjan als Landwirt, Fütterungsberater oder Tierarzt mit der Pro-Version für Ihren Desktop.':
    'The ration calculation programm fodjan smart feeding is made for dairy cow farmers and evaluates the health of your feedmix, for preventing e.g. rumen acidoses, milk fever and parturient paresis. At the same time you get an overview of the economic figures of your farm and the chance to optimize your ration regarding feed costs, amount of milk, IOFC etc. We give you the force to react to actual regulations e.g. to feed GMO free. Test fodjan now as farmer, feed adviser or veterinarian with the pro-version for your computer.',
  'Das Rationsberechnungsprogramm smart feeding gibt es nun auch speziell für die Schweinemast mit 2-, 3-, 4- oder 5-phasiger Fütterung. Sie können die Futtergesundheitsbewertungen Ihrer Rationen einsehen und so die Tiergesundheit steigern. Gleichzeitig haben Sie einen Überblick über Ihre Futterkosten und die Möglichkeit zur Optimierung Ihrer Ration nach Futterkosten, Energie, Proteindichte und weiteren Inhaltsstoffen. Wir geben Ihnen zudem die Möglichkeit auf aktuelle Regulatorien – wie z.B. Düngeverordnung - zu reagieren. Probieren Sie fodjan als Landwirt, Fütterungsberater oder Tierarzt mit der Pro-Version für Ihren Desktop.':
    'The ration calculation program fodjan smart feeding is now available for pig production. You can check the health of your feedmix and find out risks for animal health at a glance. Simultaneously you become an overview of your feedstuff costs and the possibility to optimize in regard to these, the rations energy, protein density and other nutrients. Test fodjan now as farmer, feed adviser or veterinarian with the pro-version for your computer.',
  'Das Rationsberechnungsprogramm smart feeding gibt es nun auch speziell für die Rindermast mit 3- oder 7-phasiger Fütterung. Sie können die Futtergesundheitsbewertungen Ihrer Rationen einsehen und somit gesundheitlichen Folgen wie Pansenazidose und Klauenerkrankungen vorbeugen. Gleichzeitig haben Sie Überblick über aktuelle wirtschaftliche Kennzahlen Ihres Betriebs und die Möglichkeit zur Optimierung Ihrer Ration hinsichtlich Futterkosten, -effizienz, uvm.  Wir geben Ihnen die Möglichkeit auf aktuelle Regulatorien – wie z.B. Düngeverordnung und GVO-freie Fütterung - zu reagieren. Probieren Sie fodjan als Landwirt, Fütterungsberater oder Tierarzt mit der Pro-Version für Ihren Desktop.':
    'The ration calculation program fodjan smart feeding is now available for beef cattle with 3-phase and 7-phase feeding. You can check the health of your feedmix and find out risks for animal health at a glance. At the same time you get an overview of the economic figures of your farm and the chance to optimize your ration regarding feed costs, etc. Test fodjan now as farmer, feed adviser or veterinarian with the pro-version for your computer.',
  'fodjan kann nicht nur Rationsberechnung, sondern ist ein Programm für das komplette Fütterungsmanagement. Sie können mehrere Betriebe verwalten und haben alle Daten an einem Ort. Mit aktuellen Kennzahlen, Auswertungen, Futtermittel- und Tiergruppenverwaltung und dem Assistenten beraten Sie Ihre Kunden noch besser und können Tierwohlrisiken in der Fütterung schnell erkennen.':
    'fodjan does your ration calculation, but aswell your whole feeding management. Manage multiple farms and have all data in one place. With modern key performance indicators, analytics, feedstuff and feeding group management and the assistant you counsel your customers better still and discern animal health and welfare risks.',
  'Mit fodjan mehr sparen, als man dafür bezahlt: fodjans smart feeding Fütterungsmanagementprogramm stellt Tiergesundheit und Wirtschaftlichkeit gemeinsam in den Fokus und passt sich Ihren Prioritäten an. Der Erfolg ist seinen Preis wert, denn mit der Futterkostenoptimierung spart man mehr als man für fodjan bezahlt. Hier finden Sie unsere Preise sowie Support und Schulungsangebote.':
    'Save more money with fodjan, as you pay for it. fodjans smart feeding management program focusses on both -animal health and economic figures. The success is worth ist price. Find out more about our prices, support and training offers on this site.',
  'fodjan hat sich der intelligenten Digitalisierung von Fütterungsprozessen in Tierproduktionsbetrieben verschrieben. Gestartet als Start Up in Dresden hat fodjan inzwischen nicht nur einige Preise ergattert, sondern auch sein Portfolio von Milchkühe auf Mastschweine und Mastrinder erweitert. Mehr Infos zum Werdegang von fodjan hier.':
    'fodjan strives for intelligent digitalization of feeding processes in animal production farms. Here you can find more information about fodjans story.',
  'Du willst unser junges Start-Up bei der Entwicklung von fodjan unterstützen? Wir freuen uns auf Deine Bewerbung. Wir bieten Stellen im Bereich Informatik, Softwareentwicklung, App-Entwicklung und Agrarberatung mit Fokus auf Tierproduktion.':
    'You want to join our young start up and help us make feeding more intelligent, healthy and rentable? Send us your aplpication on informatics, software engineering, app development or agricultural consulting with focus on animal production.',
  'Im Pressebereich von fodjan finden Sie Pressemitteilungen, unseren Pressespiegel, Ansprechpartner sowie Bilder und mehr.':
    'In our online press lounge you can find relevant media about fodjan – press releases and reviews, pictures and more.',
  'Registrieren und direkt loslegen. Hier können Sie sich und Ihre Milchkühe, Mastrinder oder Schweine für die kostenlose Testphase von fodjan Pro anmelden oder die fodjan App für Android oder iOS downloaden. Gern schulen wir Sie auch im Umgang mit fodjan oder unterstützen Sie beim Einrichten Ihres Betriebes.':
    'Sign up and get started. We will be glad to train you individually on fodjan and support you in setting up your farm.',
  'fodjan für Milchkühe': 'fodjan for Dairy Cows',
  'fodjan für Schweine': 'fodjan for Pigs',
  'fodjan für Mastrinder': 'fodjan for Beef Cattle',
