    'Improved Workflow Through App Integration',
  'Zugriff von jedem Ort': 'Access from any location',
  'Rationen an Fütterer via App': 'Rations to Feeder via App',
  'Vernetzen mit Labor, Berater & Technik':
    'Connect with lab, advisers & technology',
  'Analysen und Fütterungstechnik': 'Analyses and feeding technology',
