  'Entwicklung Kennzahlen': 'Development of key figures',
  'Vergleich Planung und Ergebnisse': 'Compare planning and results',
  'Ihr persönlicher Fütterungsassistent': 'Your Personal Feeding Assistant',
  'fodjan ist eine webbasierte Plattform zum Fütterungsmanagement, dazu zählen die Rationsgestaltung, das Futtermanagement und die Vernetzung von Daten, Technik und Beratern in landwirtschaftlichen Betrieben. Der Zugang erfolgt via Internet über die Software fodjan pro oder die fodjan App. fodjan versteht sich als Werkzeug um die Fütterung der Nutztiere gesünder zu gestalten und gleichzeitig Futterkosten und Futtereffizienz im Griff zu haben und zu verbessern. Auf der Plattform werden fütterungsrelevante Daten vereint und für den Anwender nutzbar und auswertbar bereitgestellt.':
    'fodjan is a web-based feed management platform that includes rationing, feed management and networking of data, technology and farm advisers. Access is via the Internet using the software fodjan per fodjan or app. fodjan sees itself as a tool to make the feeding of livestock healthier and to control and improve feed costs and feed efficiency at the same time. On the platform feeding relevant data are combined and provided useful and evaluable for the user.',
  Kooperationen: 'Cooperations',
  'Lely und fodjan mit neuer Partnerschaft.':
    'Lely and fodjan with new partnership.',
  'Lely und fodjan kooperieren in der Entwicklung':
    'Lely and fodjan cooperate in development',
  'Für Milchviehbetriebe ist die Fütterung ein wichtiger Erfolgs- und Kostenfaktor. Daher wollen wir zusammen mit der %s%Lely Gruppe%t% aus den Niederlanden unsere innovative Fütterungssoftware weiter entwickeln und die Vernetzung des Milchviehstalls vorantreiben.':
    'For dairy farms, feeding is an important success factor and cost factor. Therefore, together with the %s%Lely Group%t% from the Netherlands, we want to further develop our innovative feeding software and advance the networking of dairy cattle.',
  'Zur Pressemitteilung': 'To Press Release',
  'Fütterrungsprofis der BayWa nutzen fodjan':
    'Feeding Professionals from BayWa Use fodjan',
  'Durch die Kooperation mit dem Agrarkonzern %s%BayWa%t% wird ein neues Produkt geschaffen, das die Rationszusammenstellung für BayWa-Kunden tiergerechter und effizienter gestaltet. Die Zusammenarbeit zwischen Landwirten und Fütterungsberater wird dadurch auf ein neues Niveau gehoben.':
    'Through the cooperation with the agricultural company %s%BayWa%t% a new product is created, which makes the rationing compilation more and more efficient for BayWa customers. The collaboration between farmers and feed advisers is thereby raised to a new level.',
  'Zur BayWa-Kooperationsseite': 'To BayWa Cooperation Page (DE)',
  'Anstehende Termine': 'Upcoming Events',
  'fodjan bei Fachveranstaltungen & Messen':
    'fodjan at Special Events & Exhibitions',
  'Lernen Sie die innovative Software für ein effizientes Futtermanagement auf einer der Veranstaltungen, auf denen wir präsent sind, kennen.':
    'Become familiar with our innovative software for an efficient feed management at one of the events we are present.',
  'Sie planen selbst eine Fachveranstaltung und würden fodjan gern mit vorstellen oder streben eine Kooperation an?':
    'You are planning an own special event and would like to introduce fodjan as well or strive for a cooperation?',
