  'Wollen Sie mehr über fodjan erfahren?': 'Want to know more about fodjan?',
  'fodjan wird unterstützt durch': 'fodjan is supported by',
  'Das sagen unsere Kunden': 'Thats what our customers say',
  'Mit der fodjan-Fütterungssoftware mache ich das Feintuning für die Futterrationen unserer 1000-köpfigen Milchviehherde. (...) Mithilfe des Programms kriege ich schnell mit, was gut ist und was nicht.':
    'With the fodjan feeding software I make the fine tuning for the rations of our 1000-strong dairy herd. (...) By using the program I realize quickly what is good and what is not.',
  'Hier geht es zum Interview': 'Read the whole interview',
  'Zum Artikel': 'To Article (DE)',
  'Endlich habe ich es geschafft, ohne viel Aufwand meine Futterkosten zu reduzieren ohne dabei Kompromisse in der Gesundheit meiner Kühe eingehen zu müssen.':
    'Finally I managed it without much effort to reduce my feed costs without any compromise in the health of my cows.',
