  'fodjan smart feeding - Rationsberechnung der neuen Generation. Hier finden Sie alle Informationen zum Datenschutz.':
    'fodjan smart feeding - ration calculation of a new generation. Here you can find all information about privacy policy.',
  'Falls Sie das Exklusivpaket "BayWa Rind" für BayWa-Kunden bestellen wollen, registrieren Sie sich bitte auf der':
    'If you would like to order the exclusive package "BayWa Rind" for BayWa customers, please register at the',
  'Website der BayWa.': 'website of BayWa',
  'Das Thema Fütterung ist ein wesentlicher Erfolgsfaktor im Milchviehbetrieb. Hierbei kommt es auf den richtigen Einsatz von Futtermitteln, die Futterbedarfsplanung, das Herdenmanagement als auch auf die Rationsberechnung an.':
    'Feeding is an essential factor of success for dairy farms. This depends on the right use of feedingstuff, the feed requirement planning, herd management as well as the ration calculation.',
  'Immer mit dem Ziel vor Augen, die richtige Balance zwischen Tiergesundheit und Kosten zu halten.':
    'Always with the end in view, to keep the right balance between animal health and costs.',
  'Hierbei unterstützt Sie fodjan smart feeding. Egal ob mit oder ohne Berater an Ihrer Seite.':
    'At this point fodjan smart feeding supports you. Whether you have an adviser by your side or not.',
  'Mit der Fütterungssoftware schaffen Sie es schnell und einfach, gesunde und kostengünstige Rationen zu finden.':
    "With the feeding software you're able to find fast and easy, healthy and reasonable rations.",
  'Betriebe mit Berater': 'Companies with adviser',
  'Betriebe, die mit Beratern zusammenarbeiten, profitieren vom umfassenden Knowhow und dem hohen Erfahrungsschatz der Experten.':
    'The companies who work together with advisers profit from the comprehensive know-how and the high experience of the experts.',
  'Hier ist fodjan ein hilfreiches Werkzeug, um Beratern mit der innovativen Fütterungssoftware unterstützend zur Seite zu stehen und mehr Transparenz zwischen Landwirt und Berater zu schaffen.':
    'At this point fodjan is a helpful tool to support advisers with the innovative feeding software and to create more transparency between farmer and adviser.',
  'Für die gemeinsame Nutzung erhalten beide einen Zugang zur Software.':
    'For the common use both receive an access to the software.',
  'Betriebe ohne Berater': 'Companies without adviser',
  'Auch für Betriebe, die ohne Berater arbeiten und die Fütterung der Milchkühe selbst in die Hand nehmen, ist fodjan ein ideales Programm, um die Futterbestände übersichtlich zu verwalten und die geeignetste Ration zu finden.':
    'Also for the companies who work without advisers and take in hand the feeding of the milk cows themselves fodjan is an ideal programme to administer the feed supplies clear and to find the most suitable ration.',
  'Viele Betriebe, auch ohne Berater, finden mit fodjan gesündere Rationen - ohne dabei mehr investieren zu müssen. Im Gegenteil: Die Betriebe sparen durchschnittlich 10 % ihrer Futterkosten ein.':
    'Many companies, also without advisers, find with fodjan healthier rations - without having to invest more. On the contrary: The companies save on an average 10% of their feed costs.',
  'Milchvieh- und Futterberater': 'Dairy - and feed advisers',
  'Sie sind Milchvieh- bzw. Futterberater und möchten Ihre Betriebe individuell und bestmöglich beraten? Mit dem innovativen Fütterungsprogramm fodjan smart feeding können Sie mehrere Betriebe gleichzeitig beraten und optimieren.':
    'You are dairy- or feed adviser and would like to advise your companies individually and in the best way possible? With the innovative feeding programme fodjan smart feeding you can advise several companies and optimise them at the same time.',
  'Ob Planung, Rationsberechnung oder Futtergesundheitsbewertung – fodjan findet für jeden Betrieb gesündere und kostengünstigere Rationen.':
    'Whether planning, ration calculation or feed health assessment – fodjan finds for every company healthier and cheaper rations.',
