  'Mehr über die App erfahren': 'Learn more about the app',
  'Buchen Sie noch <strong>bis zum 15. Januar</strong> fodjan Pro oder den Standard Beraterzugang für ein Jahr und sparen Sie 100€. Testen Sie fodjan wie gewohnt 14 Tage kostenlos und geben Sie anschließend folgenden Gutscheincode beim Buchen der Lizenz ein:':
    'Book fodjan Pro or the Standard Adviser Account for one year <strong>until January 15th</strong> and save $100. As usual, try fodjan 14 days for free and then enter the following coupon code when you book the license:',
  'Das Buchungsformular finden Sie wie folgt: Login -> Verwaltung -> Lizenz buchen':
    'The booking form can be found as follows: Login -> Administration -> Book License',
  'fodjan smart feeding Milchkuh ist eine interaktive und internetbasierte Software zur Futterrationsberechnung für Milchkühe. Das innovative Programm ermöglicht erstmals eine Verbesserung der Tiergesundheit bei gleichzeitiger Reduktion der Futterkosten. Durch einen speziell entwickelten Algorithmus erspart fodjan smart feeding dem Nutzer das zeitaufwändige Ausprobieren verschiedener Futterrationen. Die Bedienung ist einfach und intuitiv gestaltet – die Rechenarbeit erledigt der Algorithmus.':
    'fodjan smart feeding Dairy Cow is an interactive and Internet-based software to calculate the feed rations for dairy cows. For the first time ever, the innovative programme allows improving animal health with simultaneous reduction of feed costs. With a specially developed algorithm, fodjan smart feeding saves users the time-consuming testing of different feed rations. Operation is simple and intuitive by design – the calculations are completed by the algorithm.',
