  'Am %a% Laktationstag nimmt eine Kuh %b% kg FM Leistungsfutter am Futtertisch und %c% kg FM an den Stationen auf':
    'El día %a% de lactación, una vaca ingiere %b% kg de pienso de rendimiento FM en la mesa de alimentación y %c% kg de FM en las estaciones.',
  'Eine Kuh mit %a% kg Milch nimmt %b% kg FM Leistungsfutter am Futtertisch und %c% kg FM an den Stationen auf':
    'Una vaca con %a% kg de leche ingiere %b% kg de pienso de rendimiento FM en el comedero y %c% kg de FM en las estaciones',
  'Menge bis "%a%". Laktationstag auf "%b%" kg FM steigern':
    'Aumentar la cantidad a 0 kg FM al 0 día de lactación.',
  'ag_lactation_day.description': ' ',
  'ag_milklact.name': 'Lactosa',
  'ag_additional_feed.description':
    'Cantidad de alimento adicional en kg FM por grupo y día para su uso en otro grupo de alimentación.',
  'Zusatzfuttermenge in kg FM pro Gruppe und Tag zur Verwendung in einer anderen Futtergruppe.':
    'Cantidad de alimento adicional en kg FM por grupo y día para su uso en otro grupo de alimentación.',
  'ag_remain_feed_kg.description':
    'Alimentación residual en MF por grupo y día',
